use vstd::prelude::*;

verus! {
    // solve takes a vector of i8.  If its length is < 3, we return an empty vector.
    // Otherwise we interpret:
    //   capacity = input[0]
    //   current  = input[1]
    //   incoming = input[2]
    // We compute leftover = max(0, incoming - (capacity - current)),
    // then clamp it to the i8 range [−128,127], and return it as a singleton vector.
    fn solve(input: Vec<i8>) -> (result: Vec<i8>)
        ensures
            // if fewer than 3 elements, result is empty
            if input.len() < 3 {
                result.len() == 0
            } else {
                // otherwise exactly one element, equal to the clamped leftover
                let capacity: i64 = input.index(0) as i64;
                let current:  i64 = input.index(1) as i64;
                let incoming: i64 = input.index(2) as i64;
                let spare:    i64 = capacity - current;
                let diff:     i64 = incoming - spare;
                let max0:     i64 = if diff > 0 { diff } else { 0 };
                let clamped:  i8  =
                    if max0 > 127 { 127 }
                    else if max0 < -128 { -128 }
                    else { max0 as i8 };
                result.len() == 1 && result.index(0) == clamped
            },
    {
        if input.len() < 3 {
            return Vec::new();
        }
        let cap = input.index(0);
        let cur = input.index(1);
        let inc = input.index(2);
        // compute spare capacity and diff
        let spare = cap.wrapping_sub(cur);
        let diff  = inc.wrapping_sub(spare);
        // max(0, diff)
        let max0 = if diff > 0 { diff } else { 0 };
        // clamp to i8 range
        let leftover: i8 =
            if max0 > 127 { 127 }
            else if max0 < -128 { -128 }
            else { max0 };
        // return singleton vector
        let mut res = Vec::new();
        res.push(leftover);
        res
    }
}

